cap = int(input())
events = list(map(int, input().split()))
filled = 0
for amt in events:
    if filled == cap:
        break
    if filled + amt > cap:
        filled = cap
    else:
        filled += amt
print(f"Filled: {filled}")
print(f"Left: {cap - filled}")

