c, level, k, t, r, n = map(int, input().split())
wasted = 0
day = 1
while day <= n:
    if level < k:
        level = 0
    else:
        level -= k
    if level == 0:
        print(f"Day {day}: 0")
        print("Crisis")
        break
    if level < t:
        level += r
        if level > c:
            wasted += level - c
            level = c
    print(f"Day {day}: {level}")
    day += 1
else:
    print(f"Wasted: {wasted}")

n, rounds = map(int, input().split())
slots = list(map(int, input().split()))
dispensed = 0
for r in range(1, rounds + 1):
    given = 0
    for i in range(n):
        if slots[i] < 0:
            continue
        if slots[i] > 0:
            slots[i] -= 1
            dispensed += 1
            given += 1
    print(f"Round {r}: {given}")
    empty = True
    for i in range(n):
        if slots[i] > 0:
            empty = False
    if empty:
        print(f"Dispenser empty after round {r}")
        break
else:
    print(f"Rounds complete, dispensed {dispensed}")

m = int(input())
values = list(map(int, input().split()))
best_steps = -1
best_val = -1
for v in values:
    x = v
    steps = 0
    while x != 1 and steps < 50:
        if x % 2 == 0:
            x //= 2
        else:
            x = 3 * x + 1
        steps += 1
    if x == 1:
        print(f"{v} -> {steps}")
        if steps > best_steps:
            best_steps = steps
            best_val = v
    else:
        print(f"{v} -> Diverged")
if best_steps == -1:
    print("None converged")
else:
    print(f"Max steps: {best_steps} for {best_val}")
